def apply(inputs,premises):
    spans=[]
    for span in inputs.get('source_spans',[]):
        if isinstance(span,dict):
            spans.append(span)
    rows=inputs.get('semantic_answers',[])
    if isinstance(rows,dict):
        value=rows.get('answers')
        if isinstance(value,list):
            rows=value
        elif isinstance(value,dict):
            rows=list(value.values())
        else:
            rows=list(rows.values())
    if not isinstance(rows,list):
        rows=[]
    answered=set()
    by_id={}
    for row in rows:
        if isinstance(row,dict) and isinstance(row.get('id'),str):
            answered.add(row.get('id'))
            by_id[row.get('id')]=row
    all_ids=[]
    positions={}
    i=0
    while i<len(spans):
        uid=spans[i].get('id')
        all_ids.append(uid)
        positions[uid]=i
        i+=1
    queries=[]
    scouts=[('disclosure_locator_v2','locate_disclosure_windows_v2'),('disposal_locator_v2','locate_disposal_windows_v2')]
    for qid,operation in scouts:
        if qid not in answered and all_ids:
            queries.append({'id':qid,'operation':operation,'unit_ids':all_ids})
    families=[('disclosure_locator_v2','disclosure',['disclosure_effect_v2','recipient_employees_v2','controlled_entity_employees_v2','recipient_contractors_v2','recipient_consultants_v2','recipient_agents_v2','recipient_professional_advisers_v2','need_to_know_v2','extent_necessary_v2','recipient_confidentiality_v2']),('disposal_locator_v2','disposal',['disposal_action_connection_v2','return_trigger_v2','destroy_trigger_v2','return_material_scope_v2','destroy_material_scope_v2','retention_effect_v2','retention_basis_v2','retention_material_scope_v2'])]
    for scout_id,prefix,operations in families:
        scout=by_id.get(scout_id)
        if not isinstance(scout,dict) or scout.get('choice')!='candidate_found':
            continue
        selected=[]
        evidence=scout.get('evidence',[])
        if isinstance(evidence,dict):
            evidence=[evidence]
        for item in evidence:
            if isinstance(item,dict) and item.get('unit_id') in positions:
                pos=positions[item.get('unit_id')]
                if pos not in selected:
                    selected.append(pos)
        selected=sorted(selected)
        groups=[]
        for pos in selected:
            if not groups or pos-groups[len(groups)-1][len(groups[len(groups)-1])-1]>2:
                groups.append([pos])
            else:
                groups[len(groups)-1].append(pos)
        for group in groups:
            start=max(0,group[0]-1)
            stop=min(len(spans)-1,group[len(group)-1]+1)
            unit_ids=[]
            j=start
            while j<=stop:
                unit_ids.append(spans[j].get('id'))
                j+=1
            suffix=str(unit_ids[0])+'_'+str(unit_ids[len(unit_ids)-1])
            for operation in operations:
                qid=prefix+'_'+operation+'__'+suffix
                if qid not in answered:
                    queries.append({'id':qid,'operation':operation,'unit_ids':unit_ids})
    return {'queries':queries}

def normalized_text(x):
    if not isinstance(x,str):
        x=str(x)
    return x.casefold().strip()

def has_any_phrase(t,phrases):
    for p in phrases:
        if p in t:
            return True
    return False

